const $ = id => document.getElementById(id);
let current = null, activeFile = '', saved = '', history = [], lastOutput = '', noticeTimer;
let runtimeOptions={},selectedTask=null;
async function waitJob(value,onProgress=()=>{}) { if(!value.job)return value;for(;;){const state=await api('/api/job?id='+value.job);onProgress(state.message);if(state.status==='done')return state.result;if(state.status==='error')throw new Error(state.error);await new Promise(resolve=>setTimeout(resolve,1500));} }
function renderFiles(){const q=$('fileFilter').value.toLowerCase();const matches=current.files.filter(name=>name.toLowerCase().includes(q));$('fileCount').textContent=`${matches.length.toLocaleString()} files${matches.length>300?' · showing first 300; filter to narrow':''}`;$('files').replaceChildren();for(const name of matches.slice(0,300)){const button=el('button',name);button.classList.toggle('active',name===activeFile);button.onclick=()=>openFile(name).catch(e=>notify(e.message));$('files').append(button);}}
function configureRuntime(){const runtime=runtimeOptions[$('runtime').value];$('command').value=current?.benchmark?'Task-specific regression suite':runtime.command;$('command').disabled=!!current?.benchmark;$('runtime').disabled=!!current?.benchmark;$('runtimeImage').value=current?.benchmark?current.image:runtime.image;$('runtimeImage').disabled=!!current?.benchmark;$('environmentNote').textContent=current?.benchmark?'Uses the benchmark’s prepared dependencies and regression test script. Test output must be inspected; completion alone is not a correctness score.':'Commands run in a disposable writable copy, without network access. Compilers are included; third-party project dependencies require a prepared image. Build outputs are discarded after each run.';}
$('fileFilter').oninput=renderFiles;
$('randomTask').onclick=e=>busy(e.currentTarget,async()=>{selectedTask=await waitJob(await api('/api/task/random',{language:$('taskLanguage').value,scope:$('taskScope').value}),text=>$('taskProgress').textContent=text);$('taskProgress').textContent=selectedTask.recycled?'You have seen all matching tasks. Starting a new rotation.':`${selectedTask.total} tasks in this rotation`;const preview=$('taskPreview');preview.hidden=false;preview.replaceChildren(el('h3',selectedTask.repo),el('p',selectedTask.brief.slice(0,1800)),el('small',`${selectedTask.id} · ${selectedTask.created.slice(0,10)} · ${selectedTask.commit.slice(0,12)}`));const start=el('button','Open this codebase','primary');start.onclick=e=>busy(e.currentTarget,async()=>{await enter(await waitJob(await api('/api/task/start',{taskId:selectedTask.id}),text=>$('taskProgress').textContent=text));$('taskProgress').textContent='';});preview.append(start);});
async function api(url, data) { const response = await fetch(url, data ? {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)} : {}); const result = await response.json(); if(!response.ok) throw new Error(result.error || 'Request failed'); return result; }
function notify(text) { $('notice').textContent=text; $('notice').hidden=false; clearTimeout(noticeTimer); noticeTimer=setTimeout(()=>$('notice').hidden=true,7000); }
async function busy(button, action) { const label=button.textContent; button.disabled=true; button.textContent='Working…'; try {await action();} catch(e){notify(e.message);} finally{button.disabled=false;button.textContent=label;} }
function el(tag, text, className) { const node=document.createElement(tag); node.textContent=text; if(className)node.className=className; return node; }
async function status() { const state=await api('/api/status'); $('health').textContent=state.docker&&state.modelReady?'●':'○'; $('setupStatus').textContent=`Docker: ${state.docker?'ready':'not running'} · Ollama: ${state.ollama?'connected':'not running'} · 0.5B helper: ${state.modelReady?'ready':'not downloaded'} · 3B interviewer: ${state.interviewerReady?'ready':'not downloaded'}`; }
$('setupButton').onclick=()=>{$('setup').showModal();status().catch(e=>notify(e.message));};
$('closeSetup').onclick=()=>$('setup').close();
$('refreshStatus').onclick=e=>busy(e.currentTarget,status);
$('pull').onclick=e=>busy(e.currentTarget,async()=>{ $('setupStatus').textContent='Downloading the model. This can take several minutes…'; await waitJob(await api('/api/model/pull',{}),text=>$('setupStatus').textContent=text); await status(); });
async function save() { if(!activeFile)return; await api('/api/file',{id:current.id,path:activeFile,content:$('editor').value}); saved=$('editor').value; $('save').textContent='Saved'; }
async function openFile(name) { if(activeFile&&$('editor').value!==saved) await save(); const file=await api(`/api/file?id=${current.id}&path=${encodeURIComponent(name)}`); activeFile=name; saved=file.content; $('editor').value=saved; $('fileName').textContent=name; $('save').textContent='Save file'; for(const button of $('files').children)button.classList.toggle('active',button.textContent===name); }
async function enter(session) { if(current&&activeFile&&$('editor').value!==saved)await save();current=session; activeFile=''; history=[]; lastOutput=''; saved=''; $('editor').value=''; $('fileName').textContent='Select a file'; $('messages').replaceChildren(el('div','Run the tests, inspect the failure, and ask me what to investigate.','message assistant')); $('output').textContent='Run the tests to establish your starting point.'; $('testState').textContent='Not run'; $('sessionTitle').textContent=session.title; $('brief').textContent=session.brief; $('source').textContent=session.source+(session.commit?' · Commit '+session.commit:'');$('fileFilter').value='';renderFiles();$('runtime').value=session.runtime||'node';configureRuntime();$('lobby').hidden=true;$('workspace').hidden=false; localStorage.setItem('debug-gym-session',session.id); const first=session.files.find(n=>n.endsWith('.mjs')&&!n.includes('.test.'))||session.files.find(n=>/^readme/i.test(n))||session.files[0]; if(first)await openFile(first);window.dispatchEvent(new CustomEvent('gym-session',{detail:session})); }
$('back').onclick=e=>busy(e.currentTarget,async()=>{if(activeFile&&$('editor').value!==saved)await save();$('workspace').hidden=true;$('lobby').hidden=false;});
$('save').onclick=e=>busy(e.currentTarget,save);
$('editor').oninput=()=>{$('save').textContent=$('editor').value===saved?'Saved':'Save changes';};
$('editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('  ',a,b,'end');e.target.dispatchEvent(new Event('input'));}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();save().catch(e=>notify(e.message));}};
window.addEventListener('beforeunload',e=>{if(activeFile&&$('editor').value!==saved){e.preventDefault();e.returnValue='';}});
$('runtime').onchange=configureRuntime;
$('run').onclick=e=>busy(e.currentTarget,async()=>{await save();$('testState').textContent='Running';$('output').textContent='Starting isolated runtime…';$('back').disabled=true;try{const result=await waitJob(await api('/api/run',{id:current.id,runtime:$('runtime').value,image:$('runtimeImage').value,command:$('command').value}),text=>$('output').textContent=text);lastOutput=result.output;$('output').textContent=result.output||'(No output)';$('testState').textContent=result.timedOut?'Timed out':result.benchmark?'Suite finished · inspect results':result.code===0?'Command passed':`Exit ${result.code}`;}catch(error){$('testState').textContent='Could not run';$('output').textContent=error.message;throw error;}finally{$('back').disabled=false;}});
$('importForm').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>enter(await api('/api/session',{url:$('repoUrl').value.trim()})));};
$('searchForm').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{const repos=await api('/api/search?q='+encodeURIComponent($('query').value));$('results').replaceChildren();if(!repos.length)$('results').append(el('p','No repositories found. Try another search.'));for(const repo of repos){const card=el('article','','repo'),a=el('a',repo.name);a.href=repo.url;a.target='_blank';a.rel='noreferrer';card.append(a,el('p',repo.description||'No description provided.'));const button=el('button','Practice with this repo');button.onclick=e=>busy(e.currentTarget,async()=>enter(await api('/api/session',{url:repo.url})));card.append(button);$('results').append(card);}});};
$('chatForm').onsubmit=e=>{e.preventDefault();const prompt=$('prompt').value.trim();if(!prompt)return;busy(e.submitter,async()=>{await save();const pending=el('div','Thinking locally…','message assistant');$('messages').append(el('div',prompt,'message user'),pending);$('prompt').value='';try{const answer=await api('/api/chat',{id:current.id,path:activeFile,prompt,history,output:lastOutput});pending.textContent=answer.content;history.push({role:'user',content:prompt},{role:'assistant',content:answer.content});}catch(error){pending.textContent=error.message;$('prompt').value=prompt;} $('messages').scrollTop=$('messages').scrollHeight;});};
setInterval(()=>{if(current){const seconds=Math.floor((Date.now()-current.started)/1000);$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}},1000);
async function init(){runtimeOptions=await api('/api/runtimes');for(const [id,r]of Object.entries(runtimeOptions)){const option=el('option',r.label);option.value=id;$('runtime').append(option);}const challenges=await api('/api/challenges');for(const [i,c]of challenges.entries()){const card=el('article','','card');card.append(el('span',`0${i+1}`,'card-number'),el('h3',c.title),el('p',c.brief));const footer=el('footer');footer.append(el('span',`${c.category} · ${c.minutes} min`));const button=el('button','Start debugging →','primary');button.onclick=e=>busy(e.currentTarget,async()=>enter(await api('/api/session',{challenge:c.id})));footer.append(button);card.append(footer);$('challenges').append(card);}await status();const id=localStorage.getItem('debug-gym-session');if(id){try{await enter(await api('/api/session?id='+id));}catch{localStorage.removeItem('debug-gym-session');}}}
init().catch(e=>notify(e.message));
window.gym={api,waitJob,enter,save,notify,el,current:()=>current,file:()=>activeFile,isDirty:()=>activeFile&&$('editor').value!==saved};
const newFileButton=el('button','+ New file');newFileButton.id='newFile';$('fileFilter').before(newFileButton);
const fileDialog=el('dialog');fileDialog.innerHTML='<form id="newFileForm"><h2>Create a source file</h2><label for="newFilePath">Relative path</label><input id="newFilePath" required maxlength="500" placeholder="src/discount-policy.js"><div class="interview-actions"><button type="button" id="cancelNewFile">Cancel</button><button class="primary">Create file</button></div></form>';document.body.append(fileDialog);
newFileButton.onclick=()=>{fileDialog.showModal();$('newFilePath').focus();};$('cancelNewFile').onclick=()=>fileDialog.close();$('newFileForm').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{if(window.gym.isDirty())await save();const name=$('newFilePath').value.trim();const result=await api('/api/file/create',{id:current.id,path:name});current.files=result.files;renderFiles();fileDialog.close();$('newFilePath').value='';await openFile(name);});};
import('./interview-ui.js').catch(e=>notify(e.message));
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_practice_session',description:'Read the active debugging session and selected source file name.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>current?{id:current.id,title:current.title,file:activeFile,benchmark:!!current.benchmark}: {active:false}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
